async function lastHunt() {
  // We are in cow area, try to find Sheep, Zombies, or any other new target
  const targets = ["Sheep", "Zombie", "Spider", "Chicken"];
  let killed = [];

  for (const target of targets) {
    const result = await bot.attack(target);
    if (result.success) {
      await sdk.waitForCondition(state => {
        const player = state.player;
        return !player || !player.combat.inCombat;
      }, 20000);
      killed.push(target);
    }
  }
  return killed;
}

return await lastHunt();

async function finalize() {
  // We are currently fighting a Cow, let's finish it and try to find Sheep or Chickens nearby
  await sdk.waitForCondition(state => {
    const player = state.player;
    return !player || !player.combat.inCombat;
  }, 20000);

  const targets = ["Sheep", "Chicken", "Zombie", "Spider"];
  let killed = [];

  for (const target of targets) {
    const result = await bot.attack(target);
    if (result.success) {
      await sdk.waitForCondition(state => {
        const player = state.player;
        return !player || !player.combat.inCombat;
      }, 15000);
      killed.push(target);
    }
  }
  return killed;
}

return await finalize();
